var i=`0720-muamba-de-galinha`;var a=`world-0720`;var t=`AO`;var s=`central-africa`;var o=4;var r=66;var l={en:`Muamba de Galinha`,ua:`Муамба з курки`};var g={en:`Muamba de Galinha is a Angola classic prepared with chicken thigh, yellow onion, okra, tomato. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Муамба з курки, страва кухні країни Ангола зі складниками: куряче стегно, жовта цибуля, бамія, помідор. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var h=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 12 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 12 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:12,i:[[`chicken-thigh`,800,`g`],[`red-palm-oil`,65,`ml`],[`yellow-onion`,200,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 50 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 50 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:50,i:[[`okra`,360,`g`],[`tomato`,350,`g`],[`palm-nut-concentrate`,210,`g`],[`garlic`,4,`clove`],[`water`,650,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`parsley`,18,`g`]]}];var m={slug:i,id:a,country:`AO`,region:s,servings:4,minutes:66,title:l,text:g,steps:h};export{t as country,m as default,a as id,r as minutes,s as region,o as servings,i as slug,h as steps,g as text,l as title};